{
  "name": "泰克 DPO4104 数字示波器",
  "name_en": "Tektronix DPO4104 Oscilloscope",
  "manufacturer": "Tektronix",
  "description": "泰克 DPO4104 是一款多通道数字示波器，可控制采集运行方式、采集长度、波形传输数据源与数据宽度，并读取通道、参考通道和数学运算波形，适用于实验中的电信号观测与波形分析。",
  "description_en": "The Tektronix DPO4104 is a multi-channel digital oscilloscope that can control acquisition state, acquisition length, waveform transfer source, and data width, and can read channel, reference, and math waveforms for electrical signal observation and waveform analysis in laboratory experiments.",
  "tag_hints": [
    "digital oscilloscope",
    "waveform acquisition",
    "SCPI control",
    "trigger control",
    "multi-channel measurement",
    "waveform transfer",
    "signal analysis"
  ],
  "actions": [
    {
      "action_name": "auto-aquisition_continuous",
      "description": "获取/设置采集是否为连续模式。",
      "description_en": "Get/set whether acquisition is in continuous mode."
    },
    {
      "action_name": "auto-aquisition_length",
      "description": "获取/设置采集长度。",
      "description_en": "Get/set the acquisition length."
    },
    {
      "action_name": "auto-aquisition_running",
      "description": "获取/设置采集运行状态。",
      "description_en": "Get/set the acquisition running state."
    },
    {
      "action_name": "auto-data_source",
      "description": "获取/设置波形传输的数据源。",
      "description_en": "Get/set the data source for waveform transfer."
    },
    {
      "action_name": "auto-data_width",
      "description": "获取/设置波形传输的数据宽度。",
      "description_en": "Get/set the data width for waveform transfer."
    },
    {
      "action_name": "auto-force_trigger",
      "description": "强制示波器产生一次触发事件。",
      "description_en": "Force the oscilloscope to generate a trigger event."
    },
    {
      "action_name": "auto-y_offset",
      "description": "获取/设置当前数据源的 Y 偏移。",
      "description_en": "Get/set the Y offset of the current data source."
    },
    {
      "action_name": "auto-channel",
      "description": "获取指定示波器通道。",
      "description_en": "Get a specific oscilloscope channel."
    },
    {
      "action_name": "auto-ref",
      "description": "获取指定参考通道。",
      "description_en": "Get a specific reference channel."
    },
    {
      "action_name": "auto-math",
      "description": "获取数学运算数据源。",
      "description_en": "Get the math data source."
    },
    {
      "action_name": "auto-name",
      "description": "获取仪器名称。",
      "description_en": "Get the instrument name."
    },
    {
      "action_name": "auto-read_waveform",
      "description": "读取波形数据。",
      "description_en": "Read waveform data."
    },
    {
      "action_name": "auto-coupling",
      "description": "获取/设置通道耦合方式。",
      "description_en": "Get/set the channel coupling mode."
    }
  ]
}

